import React, { useRef } from 'react';

function FeaturesSection() {
  // 스크롤 슬라이더를 제어하기 위한 참조 변수
  const scrollRef = useRef(null);

  // 💡 폴더에 있는 6개의 이미지와 각각에 맞는 제목/설명을 연결했습니다.
  const specials = [
    { title: 'Dolby Cinema', desc: '돌비 시네마 고화질·고음질', img: '/img/01/01.png' },
    { title: 'Dolby Vision & Atmos', desc: '완벽한 시각과 청각의 조화', img: '/img/01/02.png' },
    { title: 'MEGA MX4D', desc: '오감을 자극하는 4D 체험', img: '/img/01/03.png' },
    { title: 'MEGA Dolby Atmos', desc: '공간을 채우는 입체 사운드', img: '/img/01/04.png' },
    { title: 'MEGA LED', desc: '차원이 다른 선명함과 색감', img: '/img/01/05.png' },
    { title: 'Boutique Private', desc: '프리미엄 프라이빗 관람관', img: '/img/01/06.png' },
  ];

  // 좌우 화살표 클릭 시 스크롤 이동 함수
  const scroll = (direction) => {
    if (scrollRef.current) {
      // 한 번 클릭할 때 300px씩 부드럽게 이동합니다.
      const scrollAmount = direction === 'left' ? -300 : 300;
      scrollRef.current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-8 border-t border-zinc-200">
      
      {/* 슬라이더 스크롤바를 안 보이게 숨겨주는 CSS 스타일 (코드 내장형) */}
      <style>
        {`
          .hide-scrollbar::-webkit-scrollbar { display: none; }
          .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        `}
      </style>

      {/* 상단 타이틀 및 슬라이더 컨트롤러 */}
      <div className="flex justify-between items-end mb-6">
        <div>
          <h3 className="text-xs font-bold text-[#503396] uppercase tracking-widest mb-1">Features Special</h3>
          <h2 className="text-xl font-extrabold text-zinc-900">Megabox Special</h2>
        </div>
        
        {/* 좌우 슬라이드 버튼 */}
        <div className="flex gap-2">
          <button onClick={() => scroll('left')} className="w-8 h-8 rounded-full border border-zinc-300 flex items-center justify-center text-zinc-500 hover:bg-[#503396] hover:text-white hover:border-[#503396] transition">
            &lt;
          </button>
          <button onClick={() => scroll('right')} className="w-8 h-8 rounded-full border border-zinc-300 flex items-center justify-center text-zinc-500 hover:bg-[#503396] hover:text-white hover:border-[#503396] transition">
            &gt;
          </button>
        </div>
      </div>

      {/* 슬라이더 리스트 영역 */}
      <div 
        ref={scrollRef}
        className="flex gap-4 overflow-x-auto snap-x snap-mandatory scroll-smooth hide-scrollbar py-2"
      >
        {specials.map((item, idx) => (
          <div 
            key={idx} 
            // 💡 한 화면에 4개씩(25%) 보여주도록 가로 크기를 맞췄습니다. (모바일에서는 1개씩)
            className="snap-start flex-none w-[85%] md:w-[calc(25%-12px)] bg-white border border-zinc-200 rounded-xl p-4 text-center hover:border-[#503396] transition shadow-sm cursor-pointer group"
          >
            {/* 💡 예매하기 버튼은 삭제하고, 이미지를 넣었습니다. 둥근 모서리와 이미지 호버 확대 효과 유지! */}
            <div className="w-full aspect-[4/3] bg-zinc-100 rounded-lg mb-4 overflow-hidden">
              <img 
                src={process.env.PUBLIC_URL + item.img} 
                alt={item.title} 
                className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
              />
            </div>
            
            <h4 className="text-sm font-bold text-zinc-900 mb-1.5">{item.title}</h4>
            <p className="text-[11px] text-zinc-500">{item.desc}</p>
          </div>
        ))}
      </div>

    </div>
  );
}

export default FeaturesSection;
